import {ROCKS,rockTop,rockInside,bed,sandBed,COAST_BOUNDS,COAST_GRID} from '../coast-v011/rock-domain.mjs';
test('enlarged domain increases area by 2.25 without coarsening cells',()=>{const s=new CoastState();assert.equal(s.nx,216);assert.equal(s.nz,168);assert.equal((s.bounds[1]-s.bounds[0])*(s.bounds[3]-s.bounds[2]),8064);assert.equal(s.dx,64/144);assert.equal(s.dz,56/112);});
test('all rock polyhedra are watertight and oriented outward',()=>{for(const r of ROCKS){const edges=new Map(),key=p=>p.map(x=>x.toFixed(6)).join(',');assert.ok(r.faces.length>=8);for(const f of r.faces){for(let i=0;i<f.vertices.length;i++){let a=key(f.vertices[i]),b=key(f.vertices[(i+1)%f.vertices.length]);let k=[a,b].sort().join('|');edges.set(k,(edges.get(k)||0)+1);assert.ok(rockInside(f.vertices[i],r,1e-6));}const p=f.vertices[0],a=p.map((x,k)=>x+f.normal[k]*.001);assert.equal(rockInside(a,r),false);}assert.ok([...edges.values()].every(n=>n===2));assert.equal(r.vertices.length-edges.size+r.faces.length,2);}});
test('visible rock faces and collider ray height are the same solid',()=>{let count=0;for(const r of ROCKS)for(const f of r.faces)if(f.normal[1]>.01){const c=[0,0,0];for(const p of f.vertices)for(let k=0;k<3;k++)c[k]+=p[k]/f.vertices.length;assert.ok(Math.abs(rockTop(c[0],c[2],r)-c[1])<1e-7);count++;}assert.ok(count>30);});
test('side disturbance does not wrap to the opposite side in one step',()=>{const s=new CoastState(flat,{nx:24,nz:20,bedFn:()=>-2,forced:false,lateralBoundary:'closed_reflecting'});for(let i=0;i<s.nx;i++)s.h[i]+=.2;const last=Array.from(s.h.slice((s.nz-1)*s.nx));s.step();for(let i=0;i<s.nx;i++)assert.ok(Math.abs(s.h[(s.nz-1)*s.nx+i]-last[i])<1e-12);});
test('expanded full grid has stable still water and no volume leak',()=>{const s=new CoastState({...flat},{forced:false});for(let i=0;i<120;i++)s.step();const st=s.stats();assert.ok(Math.abs(st.massResidualM3)<1e-7);assert.equal(st.numericalCorrectionM3,0);assert.ok(st.maxSpeed<1e-10);});

test('open sides account outgoing water and do not wrap a disturbance',()=>{const s=new CoastState(flat,{nx:24,nz:20,bedFn:()=>-2,forced:false});for(let i=0;i<s.nx;i++)s.qz[i]=-.4;s.initialVolume=s.volume();run(s,30);const q=s.stats();assert.ok(q.boundaryOutflowM3>0);assert.ok(Math.abs(q.massResidualM3)<1e-8);assert.equal(q.lateralBoundary,'open_extrapolated');assert.ok(q.lateralFluxM3<0);});
test('open sides account incoming water separately',()=>{const s=new CoastState(flat,{nx:24,nz:20,bedFn:()=>-2,forced:false});for(let i=0;i<s.nx;i++)s.qz[i]=.4;s.step();assert.ok(s.stats().boundaryInflowM3>0);assert.ok(Math.abs(s.stats().massResidualM3)<1e-8);});
test('exterior foam is empty at an open boundary',()=>{const s=new CoastState(flat,small);s.foam.fill(.6);assert.equal(s.sampleFoam(0,s.bounds[2]-1),0);assert.ok(s.sampleFoam(0,0)>.59);});
test('outgoing spray is counted as a nonmass appearance tracer',()=>{const s=new CoastState(flat,{...small,forced:false});s.spray.push({x:s.bounds[0]-1,y:20,z:0,vx:0,vy:0,vz:0,age:0,life:10,size:.05});const volume=s.volume();s.step();assert.equal(s.spray.length,0);assert.equal(s.sprayExitCount,1);assert.ok(Math.abs(s.volume()-volume)<1e-8);});
test('unknown boundary and invalid grid are refused',()=>{assert.throws(()=>new CoastState(flat,{lateralBoundary:'wrap'}));assert.throws(()=>new CoastState(flat,{nx:NaN}));});
